				}

				socket.onmessage = (message) => {
					const received = JSON.parse(message.data);
					console.log(received);

					if (received.type === 'Results' && received.channel) {
						let transcript = received.channel.alternatives[0].transcript;
					
						if (transcript && received.is_final) {
							const escapeRegExp = (string) => {
								return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
							}

							const eraseSpaceBeforeChar = (str, charToFind) => {
								charToFind = escapeRegExp(charToFind)
								const regex = new RegExp(`\\s(${charToFind})`, 'g')
								return str.replace(regex, '$1')
							}
					
							Object.keys(symbol).map((item) => {
								if (transcript.includes(item)) {
									let regex = new RegExp(item, 'g')
									transcript = eraseSpaceBeforeChar(transcript, item)
									transcript = transcript.replace(regex, symbol[item])
								}
							})
