		const audioVisualize = function(a) {
			ctx.clearRect(0, 0, audioCanvas.width, audioCanvas.height);
			var d = .5 * audioCanvas.height,
				c = audioCanvas.width / analyser.frequencyBinCount;
			var m = .5 * audioCanvas.height;
			var e = new w(analyser.frequencyBinCount),
				f = null;
			f = function() {
				window.requestAnimationFrame(f);
				analyser.getFloatTimeDomainData(e);
				ctx.fillStyle = "#eeeeee";
				ctx.fillRect(0, 0, audioCanvas.width, audioCanvas.height);
				ctx.lineWidth = 1;
				ctx.strokeStyle = "#436f8e";
				ctx.beginPath();
				for (var a = 0, h = e.length; a < h;) {
					var g = a++;
					ctx.lineTo(g * c, e[g] * m + d)
				}
				ctx.stroke()
			};
			f()
		};
	}

	const stopTranscription = async () => {
		console.log('click stop button');
		status = false;

		if (socket && socket.readyState === WebSocket.OPEN) {
			socket.close();
		}
		
		if (mediaRecorder && mediaRecorder.state !== 'inactive') {
			mediaRecorder.stop();
			socketMedia.stop();
			
			rotateCassette()
						
			transcripteStatus.remove()
			
			recordingBtn.classList.remove('recorder-btn-pressed')
			dictaRecord.classList.remove('dicta-record-pressed')
