	const transformCenter = () => {
		let g = window.document.querySelectorAll(".circle");
		for(let i = 0; i < g.length; i++) {
			let bbox = g[i].getBBox();
			let centerX = bbox.x + bbox.width / 2;
			let centerY = bbox.y + bbox.height / 2;
			g[i].style.transformOrigin = `${centerX}px ${centerY}px`;
		}
	}
	
	const rotateCassette = () => {
		console.log('rotate', status);
		let g = window.document.querySelectorAll(".circle")
		
		if(status) {
			for(let i = 0; i < g.length; i++) {
				g[i].classList.add("rotate-pressed")
			}
			light.classList.add("up")
		} else {
			for(let i = 0; i < g.length; i++) {
				g[i].classList.remove("rotate-pressed");
			}
			light.classList.remove("up")
		}
	}
	
	const formatTime1 = (seconds) => {
		let hours = Math.floor(seconds / 3600); // calculating hours
		let minutes = Math.floor((seconds % 3600) / 60); // calculating minutes
		let remainingSeconds = seconds % 60; // calculating remaining seconds

		// formatting the time with leading zeros
		let formattedTime = 
			hours === 0 ? `${padZero(minutes)}:${padZero(remainingSeconds)}` 
		: `${hours}:${padZero(minutes)}:${padZero(remainingSeconds)}`;
		return formattedTime;
	}
	
	const navigateToFirst = () => {
		if(isPlaying) {
			pauseBtn.click()
		}
		
		lastScreen.style.display = 'none'
		guidScreen.style.display = 'flex'
		textToolBar.style.flexDirection = 'row'
		editorArea.innerHTML = ''
		
		progress.querySelector("#progress #percentage").style.width = '0%'
		percentage.querySelector("div span").innerHTML = ''
	}
	
	const navigateToLast = () => {
		totalTime.innerHTML = formatTime1(Math.round(audioBuffer.duration));
		guidScreen.style.display = 'none'
		lastScreen.style.display = 'flex'
		textToolBar.style.flexDirection = 'column'
	}
	
	playBtn.addEventListener('click', () => {
		if(end) {
			progress.querySelector("#progress #percentage").style.width = '0%';
		}
		end = false;
		
		playBtn.style.display = 'none';
		pauseBtn.style.display = 'block';
		
		dictaPlay.classList.add('dicta-play-pressed')
		
		audio.play();
		replayInterval = setInterval(() => {
			let percentage = progress.querySelector("#progress #percentage");
			percentage.style.width = audio.currentTime / audioBuffer.duration * 100 + "%";

			let current = textToolBar.clientWidth * audio.currentTime / audioBuffer.duration;

			if(current < 55 || textToolBar.clientWidth - current < 55) {
				percentage.querySelector("div span").innerHTML = "";
			} else {
				percentage.querySelector("div span").innerHTML = formatTime1(Math.round(audio.currentTime));
			}
		}, 100);
		
		status = true;
		rotateCassette();
	});
	
	progress.querySelector("#progress").addEventListener("click", (e) => {
		const timeToSeek = e.offsetX / parseInt(textToolBar.clientWidth) * audioBuffer.duration;
		percentage.style.width = timeToSeek / audioBuffer.duration * 100 + "%";
		audio.currentTime = timeToSeek;
	})
	
	pauseBtn.addEventListener('click', () => {
		playBtn.style.display = 'block';
		pauseBtn.style.display = 'none';
		
		audio.pause();
		clearInterval(replayInterval);
		dictaPlay.classList.remove('dicta-play-pressed')
		
		status = false;
		rotateCassette();
	});
	
	const setSelectValue = (value) => {
		let selectElement = document.getElementById('lang');
		let options = selectElement.options;
		let isValueValid = false;

		for (let i = 0; i < options.length; i++) {
			if (options[i].value === value) {
				isValueValid = true;
				break;
			}
		}

		if (isValueValid) {
			selectElement.value = value === 'en' ? 'en_US' : value;
		}
	}
	
	transformCenter();
	setSelectValue(current_language);
	
